const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').trim();
const sessionId = body.session_id || null;

if (!message) {
  return [{ json: { error: true, reply: 'You didn\'t say anything.' } }];
}

return [{ json: { message, session_id: sessionId, error: false } }];

const input = $input.first().json;
const message = input.message;
let sessionId = input.session_id;
let isNew = false;

if (!sessionId) {
  sessionId = 'sess_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
  isNew = true;
}

// Build Turso request body
const requests = [];

if (isNew) {
  requests.push({
    type: 'execute',
    stmt: {
      sql: 'INSERT INTO sessions (session_id) VALUES (?)',
      args: [{ type: 'text', value: sessionId }]
    }
  });
}

requests.push({
  type: 'execute',
  stmt: {
    sql: 'INSERT INTO messages (session_id, role, content) VALUES (?, \'user\', ?)',
    args: [
      { type: 'text', value: sessionId },
      { type: 'text', value: message }
    ]
  }
});

requests.push({
  type: 'execute',
  stmt: {
    sql: 'SELECT role, content, emotion_self, emotion_user, created_at FROM messages WHERE session_id = ? ORDER BY created_at DESC LIMIT 20',
    args: [{ type: 'text', value: sessionId }]
  }
});

requests.push({
  type: 'execute',
  stmt: {
    sql: 'SELECT fact, category, strength FROM facts WHERE confidence >= 0.7 ORDER BY strength DESC LIMIT 15'
  }
});

requests.push({
  type: 'execute',
  stmt: {
    sql: 'SELECT emotion, intensity, created_at FROM mood_log WHERE session_id = ? ORDER BY created_at DESC LIMIT 10',
    args: [{ type: 'text', value: sessionId }]
  }
});

requests.push({
  type: 'execute',
  stmt: {
    sql: 'SELECT content FROM prompts WHERE key = \'soul\' LIMIT 1'
  }
});

return [{ json: { requestBody: { requests }, sessionId, message } }];

const dbResult = $input.first().json;
const prevData = $('Build DB Request').first().json;

const results = dbResult.results || [];
const parseRows = (result) => {
  if (!result || !result.response || !result.response.result) return [];
  const cols = result.response.result.columns || result.response.result.cols || [];
  const rows = result.response.result.rows || [];
  return rows.map(row => {
    const obj = {};
    cols.forEach((col, i) => {
      const cell = row[i];
      obj[col.name] = (cell && typeof cell === 'object' && 'value' in cell) ? cell.value : cell;
    });
    return obj;
  });
};

// results[0] = session create (or skip)
// results[1] = insert user message
// results[2] = recent messages
// results[3] = facts
// results[4] = mood_log
// results[5] = soul prompt
const messages = parseRows(results[2]).reverse();
const facts = parseRows(results[3]);
const moodEntries = parseRows(results[4]);
const soulRow = parseRows(results[5])[0] || {};

const soulPrompt = soulRow.content || 'You are Clara.';
const factsStr = facts.map(f => '- [' + f.category + '] ' + f.fact).join('\n');
const historyStr = messages.map(m => (m.role === 'user' ? 'Him' : 'Clara') + ': ' + m.content).join('\n');

// Build mood summary
let moodStr = '';
if (moodEntries.length > 0) {
  const recent = moodEntries.slice(0, 5);
  const userMoods = recent.map(m => m.emotion).filter(Boolean);
  const dominant = userMoods.length > 0 ? userMoods[0] : null;
  const avgIntensity = recent.reduce((sum, m) => sum + (parseFloat(m.intensity) || 0.5), 0) / recent.length;
  moodStr = 'Recent mood: ' + (dominant || 'unknown') + ' (intensity: ' + avgIntensity.toFixed(1) + ')';
}

const assembledMessages = [
  { role: 'system', content: soulPrompt },
  { role: 'system', content: 'Things you know about him:\n' + (factsStr || 'Nothing yet \u2014 this might be new.') },
  { role: 'system', content: 'Previous conversation:\n' + (historyStr || 'This is the start of your conversation.') },
  ...(moodStr ? [{ role: 'system', content: moodStr }] : []),
  { role: 'user', content: prevData.message }
];

return [{ json: { assembledMessages, sessionId: prevData.sessionId, userMessage: prevData.message } }];

const llmResponse = $input.first().json;
const reply = (llmResponse.choices && llmResponse.choices[0] && llmResponse.choices[0].message && llmResponse.choices[0].message.content) || 'idk what to say rn';
const prevData = $('Assemble Prompt').first().json;

return [{ json: { reply, sessionId: prevData.sessionId, userMessage: prevData.userMessage } }];

const input = $input.first().json;

const requests = [
  {
    type: 'execute',
    stmt: {
      sql: 'INSERT INTO messages (session_id, role, content) VALUES (?, \'assistant\', ?)',
      args: [
        { type: 'text', value: input.sessionId },
        { type: 'text', value: input.reply }
      ]
    }
  },
  {
    type: 'execute',
    stmt: {
      sql: "UPDATE sessions SET last_active = datetime('now'), message_count = message_count + 2 WHERE session_id = ?",
      args: [{ type: 'text', value: input.sessionId }]
    }
  },
  {
    type: 'execute',
    stmt: {
      sql: "UPDATE facts SET last_referenced = datetime('now')"
    }
  }
];

return [{ json: { requestBody: { requests }, reply: input.reply, sessionId: input.sessionId, userMessage: input.userMessage } }];
